    /// Where the item comes from, as a player knows it: "Wailing Caverns: Mutanus the Devourer", "Blacksmithing", "The League of Arathor".
    public let source: String
    /// The drop chance as a fraction (0.333333 is one in three), at the pick's own source; a pick promoted past an item the client has not confirmed carries the chance of its own source. Null when the source states no rate (every quest, vendor, crafted, reputation and PvP source, and a drop whose loot table gives none).
    public let chance: Double?

    public init(
        id: Int,
        name: String,
        source: String,
        chance: Double? = nil
    ) {
        self.id = id
        self.name = name
        self.source = source
        self.chance = chance
    }
}

