        upgrades = try c.decodeIfPresent([HomeUpgrade].self, forKey: .upgrades) ?? []
        alreadyBest = try c.decodeIfPresent([HomeAlreadyBest].self, forKey: .alreadyBest) ?? []
        talents = try c.decode(HomeTalents.self, forKey: .talents)
