        substitutions = try c.decodeIfPresent([Substitution].self, forKey: .substitutions) ?? []
        dps = try c.decode(Estimate.self, forKey: .dps)
        delta = try c.decode(Estimate.self, forKey: .delta)
        group = try c.decode(Int.self, forKey: .group)
    }
}

