    public let level: Int?
    /// A spec slug, e.g. warrior-arms; null without gear consent
    public let spec: String?
    /// The gear gap the member's addon announced (contract 2's hello); may be negative; null without gear consent
    public let gearGap: Int?
    /// The build name the member's addon announced; null when it announced none or without gear consent
    public let build: String?
    /// The sender's local time, YYYY-MM-DD HH:MM, as stored
    public let seenAt: String
    /// When the site received the snapshot (addon_snapshot.received_at), RFC 3339 UTC
    public let snapshotAt: Date

    public init(
        level: Int? = nil,
        spec: String? = nil,
        gearGap: Int? = nil,
        build: String? = nil,
        seenAt: String,
        snapshotAt: Date
    ) {
        self.level = level
        self.spec = spec
        self.gearGap = gearGap
        self.build = build
        self.seenAt = seenAt
        self.snapshotAt = snapshotAt
    }
}

