    public let statsSource: String
    public let setId: Int?
    public let unique: Bool
    public let clientUnconfirmed: Bool
    public let iconSource: String
    public let weaponType: String?
    public let supersededBy: Int?

    public init(
        id: Int,
        name: String,
        icon: String,
        slot: String,
        quality: Int,
        requiredLevel: Int,
        requiredLevelSource: String,
        itemLevel: Int,
        armor: Int,
        stats: [String: Int] = [:],
        percentStats: [String: Int] = [:],
        damageMin: Double,
        damageMax: Double,
        speed: Double,
        dps: Double,
        twoHand: Bool,
        effectText: String,
        statsSource: String,
        setId: Int? = nil,
        unique: Bool,
        clientUnconfirmed: Bool,
        iconSource: String,
        weaponType: String? = nil,
        supersededBy: Int? = nil
    ) {
        self.id = id
        self.name = name
        self.icon = icon
        self.slot = slot
        self.quality = quality
        self.requiredLevel = requiredLevel
        self.requiredLevelSource = requiredLevelSource
        self.itemLevel = itemLevel
        self.armor = armor
        self.stats = stats
        self.percentStats = percentStats
        self.damageMin = damageMin
        self.damageMax = damageMax
        self.speed = speed
        self.dps = dps
        self.twoHand = twoHand
        self.effectText = effectText
        self.statsSource = statsSource
        self.setId = setId
        self.unique = unique
        self.clientUnconfirmed = clientUnconfirmed
        self.iconSource = iconSource
        self.weaponType = weaponType
