/// GET /v1/me's data (Go auth.Me): who you are, your characters, your guilds and what you may use. The apps gate a feature on entitlements only.
public struct Me: Codable, Sendable, Equatable {
    public let user: AppUser
    public let characters: [AccountCharacter]
    public let guilds: [AccountGuild]
    public let entitlements: Entitlements
    /// Unseen finished server runs, newest first, at most three; [] without server_sims.
    public let finishedSims: [FinishedSim]
    public let discordLinkAvailable: Bool
    public let discordLink: DiscordLink?
    public let discordLinkSuggested: String?
    /// Omitted until the account picks a main.
    public let mainCharacterKey: String?
    /// Omitted when the Battle.net import never ran.
    public let bnetImportedAt: Date?
    /// Omitted when the server has no sims store configured.
    public let serverSims: ServerSimsUsage?
    /// Omitted when the deployment has notifications off.
    public let notifications: MeNotifications?
    /// Go auth.MeSeat; omitted when none.
    public let seat: JSONValue?
    /// Go auth.MeSeatOffer; omitted when none.
    public let seatOffer: JSONValue?
    /// Go auth.MeEndedSeat; omitted when none.
    public let endedSeat: JSONValue?

    public init(
        user: AppUser,
        characters: [AccountCharacter] = [],
        guilds: [AccountGuild] = [],
        entitlements: Entitlements,
        finishedSims: [FinishedSim] = [],
        discordLinkAvailable: Bool,
        discordLink: DiscordLink? = nil,
        discordLinkSuggested: String? = nil,
        mainCharacterKey: String? = nil,
        bnetImportedAt: Date? = nil,
        serverSims: ServerSimsUsage? = nil,
        notifications: MeNotifications? = nil,
        seat: JSONValue? = nil,
        seatOffer: JSONValue? = nil,
        endedSeat: JSONValue? = nil
    ) {
        self.user = user
        self.characters = characters
        self.guilds = guilds
        self.entitlements = entitlements
        self.finishedSims = finishedSims
        self.discordLinkAvailable = discordLinkAvailable
        self.discordLink = discordLink
        self.discordLinkSuggested = discordLinkSuggested
        self.mainCharacterKey = mainCharacterKey
        self.bnetImportedAt = bnetImportedAt
        self.serverSims = serverSims
        self.notifications = notifications
        self.seat = seat
        self.seatOffer = seatOffer
        self.endedSeat = endedSeat
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        user = try c.decode(AppUser.self, forKey: .user)
        characters = try c.decodeIfPresent([AccountCharacter].self, forKey: .characters) ?? []
        guilds = try c.decodeIfPresent([AccountGuild].self, forKey: .guilds) ?? []
        entitlements = try c.decode(Entitlements.self, forKey: .entitlements)
        finishedSims = try c.decodeIfPresent([FinishedSim].self, forKey: .finishedSims) ?? []
        discordLinkAvailable = try c.decode(Bool.self, forKey: .discordLinkAvailable)
        discordLink = try c.decodeIfPresent(DiscordLink.self, forKey: .discordLink)
        discordLinkSuggested = try c.decodeIfPresent(String.self, forKey: .discordLinkSuggested)
        mainCharacterKey = try c.decodeIfPresent(String.self, forKey: .mainCharacterKey)
        bnetImportedAt = try c.decodeIfPresent(Date.self, forKey: .bnetImportedAt)
        serverSims = try c.decodeIfPresent(ServerSimsUsage.self, forKey: .serverSims)
        notifications = try c.decodeIfPresent(MeNotifications.self, forKey: .notifications)
        seat = try c.decodeIfPresent(JSONValue.self, forKey: .seat)
        seatOffer = try c.decodeIfPresent(JSONValue.self, forKey: .seatOffer)
        endedSeat = try c.decodeIfPresent(JSONValue.self, forKey: .endedSeat)
    }
}

