        engineVersion: String? = nil,
        flagged: String? = nil,
        fights: [FightEntry] = [],
        players: [String] = [],
        createdAt: Date,
        lastUploadAt: Date? = nil,
        heartbeatAt: Date? = nil,
        loggingCharacter: ReportLoggingCharacter? = nil,
        dataBaseUrl: String
    ) {
        self.id = id
        self.title = title
        self.visibility = visibility
        self.owner = owner
        self.guild = guild
        self.zone = zone
        self.status = status
        self.engineVersion = engineVersion
        self.flagged = flagged
        self.fights = fights
        self.players = players
        self.createdAt = createdAt
        self.lastUploadAt = lastUploadAt
        self.heartbeatAt = heartbeatAt
        self.loggingCharacter = loggingCharacter
        self.dataBaseUrl = dataBaseUrl
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        id = try c.decode(String.self, forKey: .id)
        title = try c.decode(String.self, forKey: .title)
        visibility = try c.decode(String.self, forKey: .visibility)
        owner = try c.decodeIfPresent(ReportOwner.self, forKey: .owner)
