public struct SimRequest: Codable, Sendable, Equatable {
    /// The short sha of the engine build, from sim/enginever.
    public let engineVersion: String
    public let spec: String
    public let source: SimRequestSource
    public let character: SimRequestCharacter
    public let encounter: SimRequestEncounter
    public let iterations: Int
    public let randomSeed: Int64?
    /// Turns one character into many sims. A request carrying it is a gear, talents or drops request, by bulk.mode; one carrying weights instead is a weights request; one carrying neither is a plain run. A request never names its own kind, and never carries both blocks.
    public let bulk: BulkSpec?
    /// Asks for stat weights instead of a DPS number.
    public let weights: WeightsSpec?
    /// Asks a healer or tank spec's plain run for the figure its role is ranked on. A healer runs against the curated heal profile's fake raid for the profile's fixed fight (duration_sec and variation are replaced) and the result carries healing; a tank runs in the curated boss fight it always does and the result carries tank. A damage spec, a bulk request and a weights request refuse it.
    public let roleMetrics: Bool?

    public init(
        engineVersion: String,
        spec: String,
        source: SimRequestSource,
        character: SimRequestCharacter,
        encounter: SimRequestEncounter,
        iterations: Int,
        randomSeed: Int64? = nil,
        bulk: BulkSpec? = nil,
        weights: WeightsSpec? = nil,
        roleMetrics: Bool? = nil
    ) {
        self.engineVersion = engineVersion
        self.spec = spec
        self.source = source
        self.character = character
        self.encounter = encounter
        self.iterations = iterations
        self.randomSeed = randomSeed
        self.bulk = bulk
        self.weights = weights
        self.roleMetrics = roleMetrics
    }
}

