        aborted: Bool? = nil,
        combos: [Combo]? = nil,
        equipped: Estimate? = nil,
        stages: [Stage]? = nil,
        weights: [StatWeight]? = nil,
        sample: [SampleCast]? = nil,
        healing: HealingResult? = nil,
        tank: TankResult? = nil
    ) {
        self.simId = simId
        self.title = title
        self.engineVersion = engineVersion
        self.request = request
        self.lane = lane
        self.dps = dps
        self.iterationsRun = iterationsRun
