        build: String,
        classId: Int,
        classSlug: String,
        trees: [TalentTree] = []
    ) {
        self.build = build
        self.classId = classId
        self.classSlug = classSlug
        self.trees = trees
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        build = try c.decode(String.self, forKey: .build)
        classId = try c.decode(Int.self, forKey: .classId)
        classSlug = try c.decode(String.self, forKey: .classSlug)
        trees = try c.decodeIfPresent([TalentTree].self, forKey: .trees) ?? []
    }
}

public struct TalentTree: Codable, Sendable, Equatable {
    public let id: Int
    public let name: String
    public let position: Int
    public let background: String
    public let icon: String
    public let talents: [Talent]

    public init(
        id: Int,
        name: String,
