/// What a tank took and made against the curated boss and the score made of it (sim/score); present only when the request set role_metrics for a tank spec.
public struct TankResult: Codable, Sendable, Equatable {
    public let dtps: Estimate
    public let tps: Estimate
    public let tmi: Estimate
    /// The character's maximum health.
    public let health: Double
    /// The hit points the boss's raw damage would take to kill the tank at the damage it actually takes.
    public let effectiveHealth: Double
    public let chanceOfDeath: Double
    /// The tank score. A bulk-pooled run computes it after pooling the three measured terms, because it is nonlinear in them.
    public let score: Estimate

    public init(
        dtps: Estimate,
        tps: Estimate,
        tmi: Estimate,
        health: Double,
        effectiveHealth: Double,
        chanceOfDeath: Double,
        score: Estimate
    ) {
        self.dtps = dtps
        self.tps = tps
        self.tmi = tmi
        self.health = health
        self.effectiveHealth = effectiveHealth
        self.chanceOfDeath = chanceOfDeath
        self.score = score
    }
}

/// Asks for stat weights instead of a DPS number.
public struct WeightsSpec: Codable, Sendable, Equatable {
    /// Engine stat ids: the Stat enum names in lower snake case - attack_power, crit, spell_haste. There is no melee_crit or spell_crit; the engine carries one hit and one crit. A stat the engine does not have is refused rather than weighed as nothing.
    public let stats: [String]
    /// The stat normalised to exactly 1.0. It is required and must be one of stats: a reference that is not among the stats being weighed would normalise against a number nobody computed. The per-spec default is reference_stat on GET /v1/specs.
    public let reference: String

    public init(
        stats: [String] = [],
        reference: String
    ) {
        self.stats = stats
        self.reference = reference
    }

    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        stats = try c.decodeIfPresent([String].self, forKey: .stats) ?? []
        reference = try c.decode(String.self, forKey: .reference)
    }
}
